pair y = 4 * w / 7;
pair x = 56 * u / 140;
pair p = IP(w--x, u--y);
pair z = IP(v--(10 * p), u--w);
draw(u--v--w--cycle);
draw(u--y);draw(x--w);draw(z--v);

